-- =====================================================================
-- migrate_rule_threshold.sql — GENERATED by sql/migrate_rule_threshold.py.
-- target: workspace.dq_triage, prefix dq_
--
-- Each key-attribute rule's threshold = its attribute's tolerance.
-- Guarded: re-running inserts nothing.
-- =====================================================================

-- Part 1 — one new version per rule whose limit differs from its attribute's tolerance
INSERT INTO workspace.dq_triage.dq_config_rule_registry (rule_id, rule_version, rule_name, target_table, target_column, cde_id, rule_type, rule_expr, scope_filter, join_sql, fail_threshold_pct, severity, business_domain, owner_group, source_layer, status, effective_from, created_by, created_at, promoted_by, promoted_at, note, template_id, template_version)
SELECT r.rule_id, r.rule_version + 1, r.rule_name, r.target_table, r.target_column, r.cde_id, r.rule_type, r.rule_expr, r.scope_filter, r.join_sql, CAST(c.tolerance_pct AS DOUBLE), r.severity, r.business_domain, r.owner_group, r.source_layer, r.status, current_timestamp(), current_user(), current_timestamp(), r.promoted_by, r.promoted_at, 'Threshold set from the key attribute\'s tolerance: thresholds live on rules since 2026-10-22. Placeholder, not business-approved.', r.template_id, r.template_version
FROM (SELECT x.*, ROW_NUMBER() OVER (PARTITION BY x.rule_id ORDER BY x.rule_version DESC) AS rn
      FROM workspace.dq_triage.dq_config_rule_registry x) r
JOIN workspace.dq_triage.dq_config_v_cde_registry_current c ON c.cde_id = r.cde_id
WHERE r.rn = 1 AND r.status <> 'retired' AND r.cde_id LIKE 'KA\\_%'
  AND c.tolerance_pct IS NOT NULL
  AND NOT (r.fail_threshold_pct <=> CAST(c.tolerance_pct AS DOUBLE));

-- 2a — EXPECTED: every limit one of the attribute tolerances (0, 0.5, 1, 2, 5).
SELECT r.fail_threshold_pct, r.status, COUNT(*) AS rules
FROM workspace.dq_triage.dq_config_v_rule_registry_current r
WHERE r.cde_id LIKE 'KA\\_%' AND r.status <> 'retired' GROUP BY 1, 2 ORDER BY 1, 2;
